function theme(mode){document.documentElement.dataset.theme=mode;try{localStorage.setItem('royalcars-theme',mode)}catch{}document.querySelectorAll('[data-theme-toggle]').forEach(b=>b.classList.toggle('active',b.dataset.themeToggle===mode));}
try{theme(localStorage.getItem('royalcars-theme')||'dark')}catch{theme('dark')}
function themeButtons(){const mode=document.documentElement.dataset.theme;return `<div class="theme-switch" role="group" aria-label="Thema"><button data-theme-toggle="light" class="${mode==='light'?'active':''}" aria-label="Licht thema" title="Licht thema">${I('sun')}</button><button data-theme-toggle="dark" class="${mode==='dark'?'active':''}" aria-label="Donker thema" title="Donker thema">${I('moon')}</button></div>`}
function can(p){return !!state.session?.user?.isOwner||state.session?.permissions?.includes(p)}
function allowedPage(p){return p==='personnel'?['hire','demote','dismiss'].some(can):can(p)}
function avatar(m,cls=''){return m.avatar&&/^https:\/\/cdn\.discordapp\.com\//.test(m.avatar)?`<img class="avatar ${cls}" src="${E(m.avatar)}" alt="" loading="lazy">`:`<span class="avatar ${cls}">${E((m.displayName||m.label||m.username||'?').slice(0,2).toUpperCase())}</span>`}
function date(v,full=false){if(!v)return '—';const d=new Date(v);if(!Number.isFinite(d.getTime()))return '—';return new Intl.DateTimeFormat('nl-NL',full?{dateStyle:'short',timeStyle:'short'}:{day:'2-digit',month:'short'}).format(d)}
function ago(v){const n=Math.max(0,Math.floor((Date.now()-new Date(v).getTime())/60000));if(!Number.isFinite(n))return '';if(n<1)return 'Zojuist';if(n<60)return `${n} min`;if(n<1440)return `${Math.floor(n/60)} uur`;return date(v)}
function rankBadge(r){return r?`<span class="rank-badge ${r.order===0?'red':r.order>2?'gray':''}">${r.order<=1?I('crown'):''}${E(r.name)}</span>`:'<span class="rank-badge gray">Geen rang</span>'}
function toast(msg){const t=document.getElementById('toast');t.textContent=msg;t.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('visible'),4500)}
async function api(url,opts={}){if(state.preview)throw Error('Dit is een ontwerpvoorbeeld. Er worden geen wijzigingen uitgevoerd.');const response=await fetch(url,{...opts,credentials:'same-origin',headers:{...(opts.body?{'Content-Type':'application/json'}:{}),...(opts.method&&opts.method!=='GET'?{'X-CSRF-Token':state.session?.csrfToken||''}:{}),...opts.headers}});let data={};try{data=await response.json()}catch{}if(response.status===401){state.session={authenticated:false};renderLogin();throw Error('Je sessie is verlopen. Log opnieuw in met Discord.')}if(!response.ok){const error=Error(typeof data.error==='string'?data.error:data.message||'Deze actie kon niet worden uitgevoerd. Probeer opnieuw.');error.status=response.status;throw error}return data}
function loginError(){const e=new URLSearchParams(location.search).get('error');if(!e)return '';const labels={access_denied:'Je hebt geen toegang tot dit portaal. Vraag de Directie om je Discord-ID toe te voegen.',unauthorized:'Je account heeft nog geen toegang. Neem contact op met de Directie.',not_configured:'De Discord-koppeling is nog niet ingesteld.',setup:'De Discord-koppeling is nog niet ingesteld.',oauth_state:'De inlogpoging is verlopen. Probeer opnieuw.',oauth_failed:'Inloggen met Discord is niet gelukt. Probeer opnieuw.',invalid_state:'De inlogpoging is verlopen. Probeer opnieuw.'};return labels[e]||'Inloggen is niet gelukt. Controleer je toegang en probeer opnieuw.'}
function renderLogin(){const ready=state.session?.configured;app.innerHTML=`<div class="login-page"><section class="login-visual"><div class="brand brand-image"><img src="/royal-cars-logo.webp" alt="Royal Cars Amersfoort"><span>MANAGEMENT PORTAL</span></div><img class="car" src="/royal-performance.webp" alt="Zwarte supersportwagen in de Royal Cars showroom"><div><h1>Excellentie begint<br>met <em>overzicht.</em></h1><p>Eén plek voor jouw mensen, jouw organisatie en alles wat Royal Cars in beweging houdt.</p></div><p class="eyebrow" style="font-size:8px;letter-spacing:2px">Royal Cars • Exclusief voor het team</p></section><section class="login-form">${themeButtons()}<div class="login-content"><div class="eyebrow">Welkom bij Royal Cars</div><h2>Jouw toegang tot<br>het management.</h2><p>Log in met je Discord-account om het portaal te openen. Alleen accounts die door de Directie zijn toegevoegd, krijgen toegang.</p>${loginError()?`<div class="error-box">${E(loginError())}</div>`:''}${ready?`<a class="button primary discord-button" href="/auth/discord">${I('discord')} Inloggen met Discord ${I('arrow')}</a>`:`<button class="button primary discord-button" disabled>${I('discord')} Discord-koppeling wordt voorbereid</button><div class="notice neutral" style="margin-top:14px;margin-bottom:0;font-size:10px">${I('info')} Het portaal staat klaar. De Directie moet de Discord-koppeling nog afronden.</div>`}<div class="login-note">${I('shield')} Beveiligde toegang via Discord</div></div><div class="login-footer">ROYAL CARS • MANAGEMENT PORTAL</div></section></div>`}
function shell(){const focused=document.activeElement;const focusId=focused?.id;const focusStart=focused?.selectionStart;const focusEnd=focused?.selectionEnd;const nav=(p,i)=>allowedPage(p)?`<a href="#${p}" data-nav="${p}" class="${state.page===p?'active':''}">${I(i)} ${paths[p][0]}</a>`:'';const bot=state.dashboard?.bot||state.session.bot||{};app.innerHTML=`<aside class="sidebar" id="sidebar"><a class="brand brand-image" href="#dashboard" aria-label="Royal Cars dashboard"><img src="/royal-cars-logo.webp" alt="Royal Cars Amersfoort"><span>MANAGEMENT PORTAL</span></a><p class="nav-label">WORKSPACE</p><nav class="nav" aria-label="Hoofdnavigatie">${nav('dashboard','grid')}${nav('members','users')}${nav('personnel','briefcase')}${nav('logs','activity')}</nav>${can('accounts')||can('settings')?`<div class="nav-section"><p class="nav-label">DIRECTIE</p><nav class="nav" aria-label="Beheer">${nav('accounts','shield')}${nav('settings','settings')}</nav></div>`:''}<div class="side-bottom"><div class="side-status"><i class="status-dot ${state.preview?'demo':bot.online?'online':''}"></i>${state.preview?'Ontwerpvoorbeeld':bot.online?'Discord verbonden':'Discord niet verbonden'}</div><div class="profile">${avatar(state.session.user,'red')}<div><strong>${E(state.session.user.displayName||state.session.user.username)}</strong><small>${state.preview?'Voorbeeldaccount':state.session.user.isOwner?'Directie · Alle rechten':E(state.session.user.groupName||'Royal Cars team')}</small></div><button class="icon-button" data-logout title="Uitloggen" aria-label="Uitloggen">${I('logout')}</button></div></div></aside><div class="shell"><header class="topbar"><div class="crumb"><button class="icon-button mobile-menu" data-mobile-menu aria-label="Menu openen">${I('menu')}</button>Royal Cars ${I('chevron')}<strong>${E(paths[state.page][0])}</strong></div><div class="top-actions"><div class="top-status"><i class="status-dot ${state.preview?'demo':bot.online?'online':''}"></i>${state.preview?'Ontwerpvoorbeeld':bot.online?'Discord verbonden':'Niet verbonden'}</div>${themeButtons()}</div></header>${state.preview?`<div class="preview-banner">${I('info')} Ontwerpvoorbeeld • Discord nog niet gekoppeld<span>Fictieve gegevens · Alle wijzigingen uitgeschakeld</span></div>`:''}<main id="main" class="main" tabindex="-1"><div class="page-heading"><div><div class="eyebrow">${E(paths[state.page][1])}</div><h1>${E(paths[state.page][2])}</h1><p>${E(paths[state.page][3])}</p></div>${state.page==='dashboard'&&can('hire')?`<a class="button primary" href="#personnel">${I('plus')} Medewerker aannemen</a>`:state.page==='members'?`<button class="button" data-refresh>${I('refresh')} Vernieuwen</button>`:''}</div><div id="page-body">${state.loading?'<div class="empty">Gegevens laden…</div>':pageContent()}</div><footer class="footer"><strong>ROYAL CARS</strong><span>${state.preview?'Ontwerpvoorbeeld met fictieve gegevens':'Management portal · Beveiligd via Discord'}</span><span>Georganiseerd. Verbonden. Vooruit.</span></footer></main></div>`;if(focusId){const next=document.getElementById(focusId);if(next){next.focus({preventScroll:true});if(typeof focusStart==='number'&&next.setSelectionRange)next.setSelectionRange(focusStart,focusEnd)}}}
function errorBox(){return state.error?`<div class="error-box">${I('info')} ${E(state.error)}</div>`:''}
function pageContent(){return errorBox()+({dashboard:dashboardView,members:membersView,personnel:personnelView,logs:logsView,accounts:accountsView,settings:settingsView}[state.page]||dashboardView)()}
function memberRows(members,compact=false){return members.map((m,i)=>`<tr><td><div class="person">${avatar(m,i%3===0?'red':i%3===1?'blue':'gold')}<div><strong>${E(m.displayName||m.username)}</strong><small>@${E(m.username||m.id)}</small></div></div></td><td>${rankBadge(m.rank)}</td><td><span class="presence">${compact?`<i class="status-dot ${state.preview?'demo':''}"></i>${state.preview?'Voorbeeld':'Actief lid'}`:E(date(m.joinedAt))}</span></td>${!compact?`<td class="muted" style="font-size:9px">${E(m.id)}</td>`:''}</tr>`).join('')}
function activityRows(logs){return logs.map(l=>`<div class="activity"><span class="activity-symbol ${E(l.type)}">${I(['hire','demote','dismiss'].includes(l.type)?l.type:'activity')}</span><div><p><strong>${E(l.targetName||l.sourceName||'Activiteit')}</strong> ${E({hire:'aangenomen',demote:'gedemoveerd',dismiss:'uit dienst'}[l.type]||'')}</p><small>${E(l.content||l.message||'Activiteit geregistreerd.')}</small></div><time datetime="${E(l.createdAt)}" title="${E(date(l.createdAt,true))}">${E(ago(l.createdAt))}</time></div>`).join('')}
function dashboardView(){const d=state.dashboard||{stats:{},recentActivity:[],bot:{}};const stats=d.stats||{},bot=d.bot||{};const metric=(icon,label,val,note,accent='')=>`<article class="metric"><span class="metric-icon">${I(icon)}</span><p>${label}</p><strong>${E(val??'—')}</strong><small class="${accent}">${accent?'<i class="status-dot online"></i>':''}${note}</small></article>`;return `<section class="hero" aria-label="Royal Cars management"><div class="hero-copy"><div class="eyebrow">Exclusief voor Royal Cars</div><h2>DRIVEN BY<br><em>EXCELLENCE.</em></h2><p>Royal Cars Amersfoort.<br>Het team achter de exclusieve ervaring.</p><div class="hero-bottom"><i></i> THE ROYAL STANDARD</div></div><img src="/royal-performance.webp" alt="Luxe sportwagen in een Royal Cars showroom"><span class="hero-caption">PRECISION IN EVERY DETAIL</span></section><div class="metrics">${metric('users','Teamleden',stats.members,state.preview?'Fictieve voorbeeldgegevens':'Medewerkers met een gekoppelde rang')}${metric('crown','Rangen',stats.ranks,'Duidelijke structuur in je team')}${metric('activity','Acties vandaag',stats.actionsToday,'Aannemen, demoten & ontslaan')}${metric('discord','Discord',state.preview?'Voorbeeld':bot.online?'Online':'Offline',state.preview?'Koppeling nog niet actief':bot.online?'Bot verbonden met jouw server':'Koppeling controleren',bot.online?'accent':'')}</div><div class="dashboard-grid"><section class="panel"><div class="panel-header"><div><h2>Jouw team</h2><p>${state.preview?'Een indruk van de live ledenlijst':'Medewerkers en hun actuele Discord-rang'}</p></div>${can('members')?'<a class="text-link" href="#members">Alle leden '+I('arrow')+'</a>':''}</div><div class="table-scroll"><table class="member-table"><thead><tr><th>MEDEWERKER</th><th>RANG</th><th>STATUS</th></tr></thead><tbody>${state.members.length?memberRows(state.members.slice(0,5),true):'<tr><td colspan="3"><div class="empty">'+I('users')+'<strong>Nog geen teamgegevens</strong>Koppel je Discord-server en stel de personeelsrangen in.</div></td></tr>'}</tbody></table></div><div class="panel-footer">${I('refresh')}${state.preview?'Voorbeeldgegevens · Geen actieve Discord-verbinding':bot.online?'Ledenlijst wordt automatisch bijgewerkt':'Wacht op Discord-koppeling'}</div></section><section class="panel"><div class="panel-header"><div><h2>Recente activiteiten</h2><p>De laatste bewegingen binnen Royal Cars</p></div>${can('logs')?'<a class="text-link" href="#logs">'+I('arrow')+'<span class="sr-only">Alle activiteiten</span></a>':''}</div><div class="activity-list">${d.recentActivity?.length?activityRows(d.recentActivity.slice(0,4)):'<div class="empty">'+I('activity')+'<strong>Een frisse start</strong>Nieuwe personeelsacties verschijnen hier.</div>'}</div><div class="panel-footer">${I('shield')} ${state.preview?'Alle namen en gebeurtenissen zijn fictief':'Activiteiten worden veilig vastgelegd'}</div></section></div>`}
function membersView(){
  return `<section class="roster-stage"><header class="roster-hero"><div class="roster-hero-copy"><span class="roster-kicker"><i></i> ROYAL CARS AMERSFOORT</span><h2>THE INNER<br><em>CIRCLE.</em></h2><p>De mensen achter de sleutels.<br>Eén team. Eén Royal Standard.</p><div class="roster-live"><i class="status-dot ${state.preview?'demo':state.session.bot?.online?'online':''}"></i>${state.preview?'Fictief ontwerpvoorbeeld':state.session.bot?.online?'LIVE VERBONDEN MET DISCORD':'WACHT OP DISCORD'}</div></div><div class="roster-emblem"><img src="/royal-cars-logo.webp" alt="Royal Cars Amersfoort"><span>THE ROYAL STANDARD / EST. AMERSFOORT</span></div><div class="roster-numbers"><div><strong>${state.members.length.toString().padStart(2,'0')}</strong><span>TEAMLEDEN</span></div><div><strong>${state.ranks.length.toString().padStart(2,'0')}</strong><span>RANGEN</span></div></div></header><div class="roster-tools"><label class="search"><span class="sr-only">Zoek medewerker</span>${I('search')}<input id="member-search" placeholder="Zoek een naam of Discord-ID…" value="${E(state.memberQuery)}"></label><select id="member-rank" aria-label="Filter op rang"><option value="">De volledige selectie</option>${state.ranks.map(r=>`<option value="${E(r.id)}" ${state.memberRank===r.id?'selected':''}>${E(r.name)}</option>`).join('')}</select><span class="roster-update">${I('refresh')}${state.preview?'Ontwerpvoorbeeld':state.membersUpdated?'Sync '+date(state.membersUpdated,true):'Nog niet gesynchroniseerd'}</span></div><div id="members-body">${rosterGroups()}</div><div class="roster-bottom"><span>ROYAL CARS / PERSONEELSDOSSIER</span><span>${state.preview?'Alle namen en gegevens zijn fictief':'Automatisch bijgewerkt · iedere 15 seconden'}</span></div></section>`;
}
function rosterGroups(){
  const query=state.memberQuery.toLowerCase();
  const rows=state.members.filter(m=>(!state.memberRank||m.rank?.id===state.memberRank)&&`${m.displayName} ${m.username} ${m.id}`.toLowerCase().includes(query));
  const ranks=state.ranks.filter(r=>(!state.memberRank||r.id===state.memberRank)&&(!query||rows.some(m=>m.rank?.id===r.id)));
  if(!ranks.length)return `<div class="roster-empty">${I('users')}<h3>${state.ranks.length?'Geen medewerkers gevonden':'Jouw selectie begint hier.'}</h3><p>${state.ranks.length?'Pas de zoekopdracht of het rangfilter aan.':'Koppel de Discord-rangen in Instellingen. De medewerkers verschijnen hier automatisch.'}</p>${can('settings')&&!state.ranks.length?'<a class="button primary" href="#settings">Rangen koppelen</a>':''}</div>`;
  return ranks.map(r=>{const members=rows.filter(m=>m.rank?.id===r.id);return `<section class="roster-rank ${r.order===0?'roster-lead':''}"><header><span class="rank-sequence">${String(r.order+1).padStart(2,'0')}</span><div><span class="roster-category">${r.order===0?'THE LEADERSHIP':'THE ROYAL TEAM'}</span><h3>${E(r.name)}</h3></div><div class="rank-rule"></div><span class="rank-total">${members.length} ${members.length===1?'LID':'LEDEN'}</span>${r.order===0?I('crown'):I('users')}</header><div class="roster-grid">${members.length?members.map((m,i)=>`<article class="royal-member"><div class="member-card-top"><span class="member-serial">RC / ${String(i+1).padStart(2,'0')}</span>${r.order===0?I('crown'):I('shield')}</div><div class="member-portrait">${avatar(m)}</div><div class="member-identity"><h4>${E(m.displayName||m.username)}</h4><p>@${E(m.username||m.id)}</p></div><div class="member-rank-label">${E(r.name)}</div><div class="member-card-bottom"><div><span>LID SINDS</span><strong>${E(date(m.joinedAt))}</strong></div><button type="button" data-copy-id="${E(m.id)}" aria-label="Kopieer Discord-ID van ${E(m.displayName||m.username)}" title="Discord-ID kopiëren">${I('discord')}<span>${E(m.id)}</span>${I('copy')}</button></div></article>`).join(''):'<p class="rank-empty">Nog geen medewerkers aan deze rang gekoppeld.</p>'}</div></section>`}).join('');
}

function pendingBanner(){return state.pendingOperations?.length?`<div id="pending-banner" class="notice">${I('info')}<div><strong>Er staat nog een Discord-bericht klaar.</strong><p>De rollen zijn al bijgewerkt. Verstuur het bericht opnieuw zonder de rollen opnieuw te wijzigen.</p>${state.pendingOperations.map((p,i)=>`<button class="button small" type="button" data-retry-operation="${i}" style="margin-top:9px">${I('refresh')} Bericht voor ${E(p.discordId)} opnieuw versturen</button>`).join('')}</div></div>`:''}
function savePending(body,remove=false){state.pendingOperations=state.pendingOperations.filter(p=>p.idempotencyKey!==body.idempotencyKey);if(!remove)state.pendingOperations.push(body);try{sessionStorage.setItem('royalcars-pending-'+state.session.user.id,JSON.stringify(state.pendingOperations))}catch{}}
function personnelView(){
  const allowed=['hire','demote','dismiss'].filter(can);if(!allowed.includes(state.action))state.action=allowed[0]||'hire';
  const labels={hire:'Medewerker aannemen',demote:'Medewerker demoten',dismiss:'Medewerker ontslaan'};
  const roles=state.personnelOptions.roles||[];
  return `${pendingBanner()}${state.preview?`<div class="notice">${I('info')} Ontwerpvoorbeeld: geen rollen of berichten worden gewijzigd.</div>`:''}<div class="forms-grid"><section class="panel"><div class="panel-header"><div><h2>Personeelsactie</h2><p>Kies de medewerker, rang en de juiste Discord-rollen.</p></div>${I('briefcase')}</div><div class="panel-body"><div class="form-tabs" role="group" aria-label="Personeelsactie">${allowed.map(t=>`<button data-action="${t}" class="${state.action===t?'active':''}">${I(t)}${{hire:'Aannemen',demote:'Demoten',dismiss:'Ontslaan'}[t]}</button>`).join('')}</div><form id="personnel-form"><div class="form-field"><label for="person-id">Discord-ID medewerker</label><input id="person-id" name="discordId" list="staff-suggestions" inputmode="numeric" pattern="[0-9]{17,20}" required placeholder="Discord-ID invullen of medewerker kiezen" autocomplete="off"><datalist id="staff-suggestions">${state.members.map(m=>`<option value="${E(m.id)}">${E(m.displayName)} — ${E(m.rank?.name||'')}</option>`).join('')}</datalist><small id="person-current">De medewerker moet in de Royal Cars Discord-server zitten.</small></div>${state.action!=='dismiss'?`<div class="form-field"><label for="person-rank">${state.action==='demote'?'Waarheen demoten?':'Op welke rang aannemen?'}</label><select id="person-rank" name="rankId" required><option value="">${state.action==='demote'?'Kies de nieuwe, lagere rang':'Kies de aanvangsrang'}</option>${state.ranks.map(r=>`<option value="${E(r.id)}">${E(r.name)}</option>`).join('')}</select><small>${state.ranks.length?'De Discord-rol van deze rang wordt automatisch toegekend.':'Voeg eerst de Discord-rangen toe bij Instellingen.'}</small></div>`:''}${state.action==='hire'?`<fieldset class="hire-role-field"><legend>Welke extra Discord-rollen?</legend><p>Vink de aanvullende rollen aan die deze medewerker moet krijgen.</p><div class="hire-role-options">${roles.length?roles.map(r=>`<label class="hire-role-option"><input type="checkbox" name="roleIds" value="${E(r.id)}"><span>${I('shield')}<strong>${E(r.name)}</strong><small>${E(r.id)}</small></span></label>`).join(''):`<div class="description">${state.preview?'Voorbeeldrollen':'Geen extra rollen beschikbaar. De Directie kan toegestane rollen toevoegen bij Instellingen.'}</div>`}</div><small>De gekozen rang${state.personnelOptions.baseRoles?.length?' en basisrollen ('+state.personnelOptions.baseRoles.map(r=>E(r.name)).join(', ')+') worden':' wordt'} automatisch toegevoegd.</small></fieldset>`:''}<div class="form-field"><label for="person-reason">Toelichting</label><textarea id="person-reason" name="reason" maxlength="1000" required placeholder="Korte toelichting voor het personeelsdossier…"></textarea><small>De toelichting verschijnt ook in het gekoppelde Discord-kanaal.</small></div><div class="form-actions"><button type="reset" class="button ghost">Wissen</button><button class="button ${state.action==='dismiss'?'danger':'primary'}" type="submit">${I(state.action)} ${labels[state.action]}</button></div></form></div></section><aside class="panel"><div class="panel-header"><h2>Van portaal naar Discord</h2></div><div class="panel-body"><ol class="info-list"><li><span class="step-number">01</span><div><strong>Kies de juiste persoon</strong><p>Gebruik het Discord-ID of de suggesties van medewerkers.</p></div></li><li><span class="step-number">02</span><div><strong>Bepaal rang en rollen</strong><p>Bij aanname kies je een rang en extra rollen. Bij demotie kies je zelf de lagere doelrang.</p></div></li><li><span class="step-number">03</span><div><strong>Controleer en bevestig</strong><p>Je ziet eerst een samenvatting. Daarna wijzigt de bot de rollen en plaatst het Discord-bericht.</p></div></li></ol><div class="notice neutral" style="margin:24px 0 0">${I('shield')} Bij ontslag worden de personeelsrollen en de bij aanname gekozen extra rollen verwijderd. Andere rollen blijven behouden.</div></div></aside></div>`;
}

function individualAccountsView(){return `<div class="notice neutral">${I('shield')} Alleen jouw vaste Directie-account beheert de toegang. Nieuwe accounts loggen in met hun eigen Discord-ID.</div><div class="forms-grid"><section class="panel"><div class="panel-header"><div><h2>Account toevoegen of wijzigen</h2><p>Gebruik hetzelfde Discord-ID om een bestaand account bij te werken.</p></div></div><div class="panel-body"><form id="account-form"><div class="form-field"><label for="account-id">Discord-ID</label><input id="account-id" name="id" inputmode="numeric" pattern="[0-9]{17,20}" required placeholder="Discord-ID van dit account"></div><div class="form-field"><label for="account-label">Naamlabel</label><input id="account-label" name="label" required maxlength="80" placeholder="Bijv. Jesse — Management"><small>Een herkenbare naam voor het accountbeheer.</small></div><div class="form-field"><label for="account-group">Beheerrang</label><select id="account-group" name="groupId"><option value="">Individuele rechten</option>${state.groups.map(g=>`<option value="${E(g.id)}">${E(g.name)}</option>`).join('')}</select><small>Een beheerrang bepaalt de rechten voor alle gekoppelde accounts.</small></div><div id="individual-access"><div class="form-field"><label>Paginarechten en acties</label><div class="permissions">${Object.entries(permissionLabels).map(([id,label])=>`<label class="check-label"><input type="checkbox" name="permissions" value="${id}">${label}</label>`).join('')}</div></div><div class="form-field"><label>Toegang tot logbronnen</label><label class="check-label" style="margin-bottom:10px"><input type="checkbox" name="allSources" checked>Alle huidige en toekomstige logbronnen</label>${state.settings?.logSources?.map(s=>`<label class="check-label" style="margin:7px 0"><input type="checkbox" name="logSourceIds" value="${E(s.id)}">${E(s.name)}</label>`).join('')||'<small>Er zijn nog geen Discord-logbronnen gekoppeld.</small>'}</div></div><div class="form-actions"><button class="button ghost" type="reset">Wissen</button><button class="button primary" type="submit" ${state.preview?'disabled':''}>${I('shield')} Account opslaan</button></div>${state.preview?'<p class="muted" style="font-size:9px;margin-top:15px">Opslaan is uitgeschakeld in het ontwerpvoorbeeld.</p>':''}</form></div></section><section class="panel"><div class="panel-header"><div><h2>Toegestane accounts <span class="count">${state.accounts.length+1}</span></h2><p>Alleen deze personen hebben toegang.</p></div></div><div class="account-card"><div class="person">${avatar(state.session.user,'red')}<div><strong>${E(state.session.user.displayName||'Directie')}</strong><small>Vaste eigenaar · Alle rechten</small></div></div><span class="rank-badge red">${I('crown')} Directie</span></div>${state.accounts.map(a=>`<article class="account-card"><div style="flex:1;min-width:0"><div class="person">${avatar({displayName:a.label},'blue')}<div><strong>${E(a.label)}</strong><small>${E(a.id)}</small></div></div><p>${a.groupId?E(state.groups.find(g=>g.id===a.groupId)?.name||'Verwijderde beheerrang — geen toegang'):a.permissions.map(p=>E(permissionLabels[p]||p)).join(' · ')||'Geen rechten'}${!a.active?' · Inactief':''}</p></div><button class="icon-button" data-edit-account="${E(a.id)}" aria-label="Account ${E(a.label)} wijzigen" title="Wijzigen">${I('edit')}</button><button class="icon-button" data-delete-account="${E(a.id)}" aria-label="Toegang van ${E(a.label)} intrekken" title="Toegang intrekken" ${state.preview?'disabled':''}>${I('trash')}</button></article>`).join('')}${!state.accounts.length?'<div class="empty">'+I('shield')+'<strong>Nog geen extra accounts</strong>Voeg een Discord-ID toe en kies de toegestane pagina’s en acties.</div>':''}</section></div>`}
function settingsView(){const s=state.settings||defaultSettings();const setup=state.session.setup||{};const status=(label,ready)=>`<div class="connection"><strong>${label}</strong><span><i class="status-dot ${ready?'online':''}"></i> ${ready?'Ingesteld':'Nog instellen'}</span></div>`;return `<form id="settings-form">${state.preview?`<div class="notice">${I('info')} Dit zijn voorbeeldinstellingen. Wijzigingen opslaan is uitgeschakeld.</div>`:''}<section class="panel settings-section"><div class="panel-header"><div><h2>Verbindingen</h2><p>De basis voor jouw Royal Cars-portaal.</p></div></div><div class="panel-body"><div class="status-grid">${status('Discord-login',setup.oauth)}${status('Discord-bot',setup.bot)}${status('Discord-server',setup.guild)}${status('Vaste eigenaar',setup.owner)}</div><p class="description" style="margin-top:17px;margin-bottom:0">Geheime sleutels worden veilig via de hosting ingesteld. Ze zijn nooit zichtbaar of aanpasbaar via dit portaal.</p></div></section><section class="panel settings-section"><div class="panel-header"><div><h2>Personeelsrangen</h2><p>Van hoog naar laag. De volgorde bepaalt of een demotie is toegestaan.</p></div><button type="button" class="button small" data-add-rank>${I('plus')} Rang toevoegen</button></div><div class="panel-body"><div class="list-labels"><span>NAAM VAN DE RANG</span><span>DISCORD ROL-ID</span></div><div id="rank-rows" class="editable-list">${s.ranks.map((r,i)=>rankRow(r,i)).join('')}</div>${!s.ranks.length?'<p class="description">Voeg de eerste rang toe om medewerkers te koppelen aan de ledenlijst.</p>':''}</div></section><section class="panel settings-section"><div class="panel-header"><div><h2>Personeelskanalen</h2><p>De bot plaatst iedere actie in het bijbehorende kanaal.</p></div></div><div class="panel-body"><div class="form-row">${[['hire','Aangenomen'],['demote','Demoties'],['dismiss','Ontslagen']].map(([id,label])=>`<div class="form-field"><label for="channel-${id}">${label} · Kanaal-ID</label><input id="channel-${id}" name="channel-${id}" inputmode="numeric" pattern="[0-9]{17,20}" placeholder="Discord kanaal-ID" value="${E(s.channels[id]||'')}"></div>`).join('')}</div><div class="form-row"><div class="form-field"><label for="base-roles">Basisrollen bij aanname</label><input id="base-roles" name="baseRoleIds" value="${E(s.baseRoleIds.join(', '))}" placeholder="Rol-ID’s, gescheiden door een komma"><small>Deze rollen worden bij aanname toegevoegd en bij ontslag verwijderd.</small></div><div class="form-field"><label for="preserve-roles">Rollen altijd behouden</label><input id="preserve-roles" name="preserveRoleIds" value="${E(s.preserveRoleIds.join(', '))}" placeholder="Rol-ID’s, gescheiden door een komma"><small>Deze rollen blijven ook bij ontslag behouden.</small></div></div></div></section><section class="panel settings-section"><div class="panel-header"><div><h2>Extra rollen bij aanname</h2><p>Bepaal welke extra Discord-rollen bevoegde accounts mogen kiezen. Jij als Directie kunt alle rollen onder de bot kiezen.</p></div></div><div class="panel-body"><label for="hire-role-ids">Toegestane extra rol-ID’s</label><input id="hire-role-ids" name="hireRoleIds" value="${E((s.hireRoleIds||[]).join(', '))}" placeholder="Rol-ID’s, gescheiden door een komma"><small class="muted">Deze lijst verleent geen websiterechten. De bot en het uitvoerende account moeten de gekozen rol kunnen beheren.</small></div></section><section class="panel settings-section"><div class="panel-header"><div><h2>Discord-logbronnen</h2><p>Voeg kanalen toe die je wilt terugzien op de logpagina.</p></div><button type="button" class="button small" data-add-source>${I('plus')} Bron toevoegen</button></div><div class="panel-body"><div id="source-rows" class="editable-list">${s.logSources.map((r,i)=>sourceRow(r,i)).join('')}</div>${!s.logSources.length?'<p class="description">Nog geen logbronnen. Voeg een bron toe en vul het Discord kanaal-ID in.</p>':''}<div class="notice neutral" style="margin-top:18px;margin-bottom:0">${I('info')} Nieuwe berichten uit ingeschakelde kanalen worden opgeslagen. Geef de bot toegang tot het kanaal en schakel waar nodig Message Content Intent in.</div></div></section><div class="settings-sticky"><p>Wijzigingen worden toegepast op de bot en het portaal.</p><button type="submit" class="button primary" ${state.preview?'disabled':''}>${I('check')} Instellingen opslaan</button></div></form>`}
function rankRow(r={},i=0){return `<div class="editable-row" data-rank-row data-id="${E(r.id||newId())}"><input aria-label="Naam rang ${i+1}" data-rank-name value="${E(r.name||'')}" placeholder="Naam van de rang" maxlength="80" required><input aria-label="Discord rol-ID rang ${i+1}" data-rank-role value="${E(r.roleId||'')}" placeholder="Discord rol-ID" inputmode="numeric" pattern="[0-9]{17,20}" required><button type="button" class="icon-button" data-remove-row aria-label="Rang verwijderen">${I('trash')}</button></div>`}
function sourceRow(s={},i=0){return `<div class="editable-row source" data-source-row data-id="${E(s.id||newId())}"><input aria-label="Naam logbron ${i+1}" data-source-name value="${E(s.name||'')}" placeholder="Naam logbron" maxlength="80" required><input aria-label="Discord kanaal-ID logbron ${i+1}" data-source-channel value="${E(s.channelId||'')}" placeholder="Discord kanaal-ID" inputmode="numeric" pattern="[0-9]{17,20}" required><label class="check-label"><input data-source-enabled type="checkbox" ${s.enabled!==false?'checked':''}>Actief</label><button type="button" class="icon-button" data-remove-row aria-label="Logbron verwijderen">${I('trash')}</button></div>`}
async function loadPage({quiet=false}={}){if(state.preview){state.error=null;shell();return}const p=state.page;if(!quiet){state.loading=true;state.error=null;shell()}try{if(p==='dashboard'){const results=await Promise.allSettled([api('/api/dashboard'),can('members')?api('/api/members'):Promise.resolve(null)]);if(results[0].status==='fulfilled')state.dashboard=results[0].value;else throw results[0].reason;if(results[1].status==='fulfilled'&&results[1].value){state.members=results[1].value.members||[];state.ranks=results[1].value.ranks||[]}}if(p==='members'){const d=await api('/api/members');state.members=d.members||[];state.ranks=d.ranks||[];state.membersUpdated=d.updatedAt}if(p==='personnel'){const options=await api('/api/personnel/options');state.personnelOptions=options;state.ranks=options.ranks||[];if(can('members')){const d=await api('/api/members');state.members=d.members||[];state.ranks=d.ranks||state.ranks}}if(p==='logs'){const q=new URLSearchParams();if(state.logSource)q.set('sourceId',state.logSource);if(state.logType)q.set('type',state.logType);if(state.logQuery)q.set('q',state.logQuery);q.set('page',String(state.logPage));const d=await api('/api/logs?'+q);state.logs=d.logs||[];state.sources=d.sources||[];state.logTotal=d.total;state.logPage=d.page||state.logPage}if(p==='accounts'){const [a,s,g]=await Promise.all([api('/api/accounts'),api('/api/settings'),api('/api/account-groups')]);state.accounts=a.accounts||[];state.groups=g.groups||[];state.settings=s.settings}if(p==='settings'){const [s,c]=await Promise.allSettled([api('/api/settings'),api('/api/discord/catalog')]);if(s.status==='fulfilled')state.settings=s.value.settings;else throw s.reason;if(c.status==='fulfilled')state.catalog=c.value}state.error=null}catch(e){state.error=e.message}finally{state.loading=false;if(state.session?.authenticated&&state.page===p){if(quiet&&['personnel','accounts','settings'].includes(p))return;shell()}}}
function navigate(){if(!state.session?.authenticated)return;const requested=location.hash.slice(1)||'dashboard';state.page=paths[requested]&&allowedPage(requested)?requested:Object.keys(paths).find(allowedPage)||'dashboard';state.error=null;loadPage();}
function openModal(html,onConfirm){const root=document.getElementById('modal-root');const prior=document.activeElement;root.innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title">${html}</section></div>`;const close=()=>{root.innerHTML='';prior?.focus()};root.querySelector('[data-cancel]')?.addEventListener('click',close);root.querySelector('[data-confirm]')?.addEventListener('click',async e=>{e.target.disabled=true;try{await onConfirm();close()}catch(err){toast(err.message);e.target.disabled=false}});root.querySelector('[data-cancel]')?.focus();const handle=e=>{if(!root.children.length){document.removeEventListener('keydown',handle);return}if(e.key==='Escape'){close();document.removeEventListener('keydown',handle)}if(e.key==='Tab'){const nodes=[...root.querySelectorAll('button:not(:disabled),a,input,select,textarea')];const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}};document.addEventListener('keydown',handle)}
async function personnelSubmit(form,existing){const f=form?new FormData(form):null;const body=existing||{type:state.action,discordId:String(f.get('discordId')).trim(),rankId:String(f.get('rankId')||''),roleIds:f.getAll('roleIds'),reason:String(f.get('reason')).trim(),idempotencyKey:newId()};const person=state.members.find(m=>m.id===body.discordId);const rank=state.ranks.find(r=>r.id===body.rankId);const title={hire:'Aanname bevestigen',demote:'Demotie bevestigen',dismiss:'Ontslag bevestigen'}[body.type];openModal(`<h2 id="modal-title">${title}</h2><p>${state.preview?'Dit is een ontwerpvoorbeeld. De actie wordt niet uitgevoerd.':'Controleer de gegevens. Na bevestiging past de bot de rollen aan en plaatst deze actie in Discord.'}</p><div class="review"><p><span>Actie</span><strong>${{hire:'Aannemen',demote:'Demoten',dismiss:'Ontslaan'}[body.type]}</strong></p><p><span>Medewerker</span><strong>${E(person?.displayName||body.discordId)}</strong></p>${rank?`<p><span>Rang</span><strong>${E(rank.name)}</strong></p>`:''}${body.roleIds?.length?`<p><span>Extra Discord-rollen</span><strong>${body.roleIds.map(id=>E(state.personnelOptions.roles.find(r=>r.id===id)?.name||id)).join(', ')}</strong></p>`:''}<p class="reason"><span>Toelichting</span><strong>${E(body.reason)}</strong></p></div><div class="modal-actions"><button class="button" data-cancel>Annuleren</button><button class="button ${body.type==='dismiss'?'danger':'primary'}" data-confirm ${state.preview?'disabled':''}>${state.preview?'Uitgeschakeld in voorbeeld':'Bevestigen & verwerken'}</button></div>`,async()=>{const d=await api('/api/personnel',{method:'POST',body:JSON.stringify(body)});if(d.operation?.status==='notification_failed'){savePending(body);const modal=document.querySelector('.modal');modal.querySelector('h2').textContent='Rollen bijgewerkt';modal.querySelector(':scope > p').textContent='De personeelsrollen zijn aangepast. Alleen het Discord-bericht moet nog worden verstuurd. Je kunt veilig opnieuw proberen.';modal.querySelector('[data-confirm]').textContent='Bericht opnieuw versturen';const page=document.getElementById('page-body');page.querySelector('#pending-banner')?.remove();page.insertAdjacentHTML('afterbegin',pendingBanner());throw Error(d.message||'Discord-bericht nog niet verstuurd. Probeer opnieuw.')}savePending(body,true);toast(d.message||'De personeelsactie is verwerkt.');form?.reset();await loadPage()})}
function settingsData(form){const split=v=>v.split(',').map(x=>x.trim()).filter(Boolean);return {ranks:[...form.querySelectorAll('[data-rank-row]')].map((row,order)=>({id:row.dataset.id,name:row.querySelector('[data-rank-name]').value.trim(),roleId:row.querySelector('[data-rank-role]').value.trim(),order})),channels:Object.fromEntries(['hire','demote','dismiss'].map(t=>[t,form.elements['channel-'+t].value.trim()])),baseRoleIds:split(form.elements.baseRoleIds.value),preserveRoleIds:split(form.elements.preserveRoleIds.value),hireRoleIds:split(form.elements.hireRoleIds.value),logSources:[...form.querySelectorAll('[data-source-row]')].map(row=>({id:row.dataset.id,name:row.querySelector('[data-source-name]').value.trim(),channelId:row.querySelector('[data-source-channel]').value.trim(),enabled:row.querySelector('[data-source-enabled]').checked}))}}
document.addEventListener('click',async e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.themeToggle){theme(b.dataset.themeToggle);return}if(b.hasAttribute('data-mobile-menu')){document.getElementById('sidebar')?.classList.toggle('open');return}if(b.hasAttribute('data-logout')){if(state.preview){location.href='/';return}try{await api('/auth/logout',{method:'POST'});location.href='/'}catch(err){toast(err.message)}return}if(b.hasAttribute('data-refresh')){loadPage();return}if(b.hasAttribute('data-log-page')){state.logPage=Number(b.dataset.logPage);loadPage({quiet:true});return}if(b.hasAttribute('data-retry-operation')){const pending=state.pendingOperations[Number(b.dataset.retryOperation)];if(pending)personnelSubmit(null,pending);return}if(b.dataset.action){state.action=b.dataset.action;shell();return}if(b.hasAttribute('data-add-rank')){document.getElementById('rank-rows').insertAdjacentHTML('beforeend',rankRow({},document.querySelectorAll('[data-rank-row]').length));return}if(b.hasAttribute('data-add-source')){document.getElementById('source-rows').insertAdjacentHTML('beforeend',sourceRow({},document.querySelectorAll('[data-source-row]').length));return}if(b.hasAttribute('data-remove-row')){b.closest('.editable-row').remove();return}if(b.dataset.editAccount){const a=state.accounts.find(x=>x.id===b.dataset.editAccount);const f=document.getElementById('account-form');f.elements.id.value=a.id;f.elements.label.value=a.label;f.elements.groupId.value=a.groupId||'';updateAccountMode();f.querySelectorAll('[name=permissions]').forEach(x=>x.checked=a.permissions.includes(x.value));f.elements.allSources.checked=a.logSourceIds?.includes('*');f.querySelectorAll('[name=logSourceIds]').forEach(x=>x.checked=a.logSourceIds?.includes(x.value));f.elements.id.focus();f.scrollIntoView({behavior:'smooth',block:'start'});return}if(b.dataset.deleteAccount){const a=state.accounts.find(x=>x.id===b.dataset.deleteAccount);openModal(`<h2 id="modal-title">Toegang intrekken?</h2><p>${E(a?.label||b.dataset.deleteAccount)} kan daarna niet meer inloggen op dit portaal. De Discord-rollen van deze persoon worden niet aangepast.</p><div class="modal-actions"><button class="button" data-cancel>Annuleren</button><button class="button danger" data-confirm>Toegang intrekken</button></div>`,async()=>{await api('/api/accounts/'+encodeURIComponent(b.dataset.deleteAccount),{method:'DELETE'});toast('De toegang is ingetrokken.');await loadPage()});return}});
document.addEventListener('submit',async e=>{if(!['personnel-form','account-form','settings-form'].includes(e.target.id))return;e.preventDefault();const form=e.target;if(form.id==='personnel-form'){personnelSubmit(form);return}if(state.preview){toast('Opslaan is uitgeschakeld in het ontwerpvoorbeeld.');return}const submit=form.querySelector('[type=submit]');submit.disabled=true;try{if(form.id==='account-form'){const f=new FormData(form);await api('/api/accounts',{method:'POST',body:JSON.stringify({id:String(f.get('id')).trim(),label:String(f.get('label')).trim(),groupId:String(f.get('groupId')||''),permissions:f.getAll('permissions'),logSourceIds:f.get('allSources')?['*']:f.getAll('logSourceIds'),active:true})});toast('Account en rechten opgeslagen.')}else{await api('/api/settings',{method:'PUT',body:JSON.stringify(settingsData(form))});toast('Instellingen opgeslagen.')}await loadPage()}catch(err){toast(err.message);submit.disabled=false}});
let searchTimer;document.addEventListener('input',e=>{if(e.target.id==='member-search'){state.memberQuery=e.target.value;document.getElementById('members-body').innerHTML=rosterGroups()}if(e.target.id==='log-search'){state.logQuery=e.target.value;state.logPage=1;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{if(state.preview){const doc=new DOMParser().parseFromString(logsView(),'text/html');document.getElementById('log-entries').innerHTML=doc.getElementById('log-entries').innerHTML}else loadPage({quiet:true})},400)}});
document.addEventListener('change',e=>{if(e.target.id==='member-rank'){state.memberRank=e.target.value;const doc=new DOMParser().parseFromString(membersView(),'text/html');document.getElementById('members-body').innerHTML=doc.getElementById('members-body').innerHTML}if(e.target.id==='log-source'||e.target.id==='log-type'){state[e.target.id==='log-source'?'logSource':'logType']=e.target.value;state.logPage=1;loadPage({quiet:true})}});
window.addEventListener('hashchange',navigate);
document.addEventListener('keydown',e=>{if(e.key==='Escape')document.getElementById('sidebar')?.classList.remove('open')});
let poll=0;setInterval(()=>{if(document.hidden||state.preview||!state.session?.authenticated||document.getElementById('modal-root').children.length)return;poll++;if(['members','logs'].includes(state.page)||state.page==='dashboard'&&poll%2===0)loadPage({quiet:true})},15000);
(async()=>{try{if(state.preview)demo();else{state.session=await api('/api/session');state.ranks=state.session.ranks||[];if(state.session.authenticated){try{const pending=JSON.parse(sessionStorage.getItem('royalcars-pending-'+state.session.user.id)||'[]');state.pendingOperations=Array.isArray(pending)?pending.filter(p=>p&&typeof p.idempotencyKey==='string'&&['hire','demote','dismiss'].includes(p.type)):[]}catch{}}}if(state.session.authenticated)navigate();else renderLogin()}catch(err){state.session={authenticated:false,configured:false};renderLogin();toast('Het portaal kon nog niet worden geladen. Vernieuw de pagina om opnieuw te proberen.')}})();

function logsView(){const rows=state.logs.filter(l=>(!state.logSource||l.sourceId===state.logSource)&&(!state.logType||l.type===state.logType)&&`${l.content} ${l.targetName} ${l.actorName}`.toLowerCase().includes(state.logQuery.toLowerCase()));return `<section class="panel"><div class="panel-header"><div><h2>Activiteitenlog <span class="count">${state.logTotal??state.logs.length}</span></h2><p>Personeelsacties en de Discord-bronnen waartoe je toegang hebt.</p></div>${can('settings')?'<a class="text-link" href="#settings">Bronnen beheren '+I('arrow')+'</a>':''}</div><div class="toolbar"><label class="search"><span class="sr-only">Zoek in logs</span>${I('search')}<input id="log-search" placeholder="Zoek in activiteiten…" value="${E(state.logQuery)}"></label><select id="log-source" aria-label="Filter logbron"><option value="">Alle bronnen</option>${state.sources.map(s=>`<option value="${E(s.id)}" ${s.id===state.logSource?'selected':''}>${E(s.name)}</option>`).join('')}</select><select id="log-type" aria-label="Filter activiteit"><option value="">Alle activiteiten</option>${[['hire','Aangenomen'],['demote','Gedemoveerd'],['dismiss','Ontslagen'],['discord','Discord-berichten']].map(([id,label])=>`<option value="${id}" ${id===state.logType?'selected':''}>${label}</option>`).join('')}</select></div><div id="log-entries">${rows.length?rows.map(l=>`<article class="log-card"><span class="activity-symbol ${E(l.type)}">${I(['hire','demote','dismiss'].includes(l.type)?l.type:'activity')}</span><div><h3>${E(l.targetName||l.sourceName||'Activiteit')} <span class="muted" style="font-weight:400">${E({hire:'· Aangenomen',demote:'· Gedemoveerd',dismiss:'· Ontslagen'}[l.type]||'')}</span></h3><p>${E(l.content||l.message||'')}</p><small>${E(l.sourceName||'Personeel')} ${l.actorName?' · Door '+E(l.actorName):''}</small></div><time datetime="${E(l.createdAt)}">${E(date(l.createdAt,true))}</time></article>`).join(''):`<div class="empty">${I('activity')}<strong>${state.logs.length?'Geen passende activiteiten':'Nog geen activiteiten'}</strong>${state.logs.length?'Pas de filters aan om meer te zien.':'Nieuwe personeelsacties en berichten uit gekoppelde kanalen verschijnen hier.'}</div>`}</div>${!state.preview&&(state.logTotal||0)>50?`<div class="toolbar" style="justify-content:space-between;border-top:1px solid var(--line)"><span class="muted" style="font-size:10px">Pagina ${state.logPage} van ${Math.ceil(state.logTotal/50)}</span><div style="display:flex;gap:8px"><button class="button small" data-log-page="${state.logPage-1}" ${state.logPage<=1?'disabled':''}>Vorige</button><button class="button small" data-log-page="${state.logPage+1}" ${state.logPage*50>=state.logTotal?'disabled':''}>Volgende</button></div></div>`:''}<div class="panel-footer">${I('shield')}${state.preview?'Fictieve activiteiten voor dit ontwerpvoorbeeld.':'Alleen bronnen waarvoor jouw account toegang heeft worden getoond.'}</div></section>`}
function groupColor(value){return /^#[a-f0-9]{6}$/i.test(value||'')?value:'#ef3b48'}
function accountsView(){
  return `<section class="access-command"><div><span class="eyebrow">DIRECTIE / TOEGANGSCONTROLE</span><h2>Jouw rangen. Jouw rechten.</h2><p>Maak een beheerrang, kies de toegestane pagina’s en voeg Discord-ID’s toe. Wijzig de rechten één keer voor de hele rang.</p></div><button class="button primary" data-new-group>${I('plus')} Beheerrang maken</button></section><div class="access-groups"><article class="access-group fixed-owner"><span class="roster-category">VASTE DIRECTIE</span><h3>${I('crown')} Directie</h3><p>Alle beheerrechten · Alleen jouw vaste Discord-account</p><span class="group-member-pill">${E(state.session.user.displayName||'Directie')}</span><small>Accountbeheer en instellingen blijven uitsluitend van jou.</small></article>${state.groups.map(g=>`<article class="access-group" style="--group-color:${groupColor(g.color)}"><div class="group-header"><span class="roster-category">BEHEERRANG</span><div><button class="icon-button" data-edit-group="${E(g.id)}" aria-label="Beheerrang ${E(g.name)} wijzigen">${I('edit')}</button><button class="icon-button" data-delete-group="${E(g.id)}" aria-label="Beheerrang ${E(g.name)} verwijderen" ${state.preview?'disabled':''}>${I('trash')}</button></div></div><h3>${E(g.name)}</h3><p>${g.permissions.map(p=>E(permissionLabels[p]||p)).join(' · ')||'Geen pagina- of actierechten'}</p><div class="group-members">${g.memberIds?.length?g.memberIds.slice(0,4).map(id=>`<span class="group-member-pill">${E(state.accounts.find(a=>a.id===id)?.label||id)}</span>`).join(''):'<span class="muted">Nog geen accounts toegevoegd</span>'}</div><button type="button" class="text-link" data-edit-group="${E(g.id)}">${g.memberIds?.length||0} ${(g.memberIds?.length||0)===1?'account':'accounts'} · Leden en rechten beheren ${I('arrow')}</button></article>`).join('')}</div>${individualAccountsView()}`;
}
function updateAccountMode(){const f=document.getElementById('account-form');if(!f)return;const inherited=Boolean(f.elements.groupId.value);document.getElementById('individual-access').hidden=inherited;document.getElementById('individual-access').querySelectorAll('input').forEach(el=>el.disabled=inherited)}
function groupEditor(group){
  const g=group||{id:newId(),name:'',color:'#ef3b48',permissions:['dashboard','members'],logSourceIds:['*'],memberIds:[]};
  openModal(`<h2 id="modal-title">${group?'Beheerrang aanpassen':'Nieuwe beheerrang'}</h2><p>Deze rechten gelden direct voor alle gekoppelde accounts. Alleen jij beheert de rangen.</p><form id="group-editor"><div class="form-row"><div class="form-field"><label for="group-name">Naam van de rang</label><input id="group-name" name="name" maxlength="80" required placeholder="Bijv. Management" value="${E(g.name)}"></div><div class="form-field"><label for="group-color">Rangkleur</label><input id="group-color" type="color" name="color" value="${groupColor(g.color)}"></div></div><fieldset class="group-permissions"><legend>Pagina’s en personeelsacties</legend><div class="permissions">${Object.entries(permissionLabels).map(([id,label])=>`<label class="check-label"><input type="checkbox" name="permissions" value="${id}" ${g.permissions.includes(id)?'checked':''}>${label}</label>`).join('')}</div></fieldset><fieldset class="group-permissions"><legend>Logbronnen</legend><label class="check-label"><input type="checkbox" name="allSources" ${g.logSourceIds.includes('*')?'checked':''}>Alle huidige en toekomstige bronnen</label>${(state.settings?.logSources||[]).map(source=>`<label class="check-label"><input type="checkbox" name="logSourceIds" value="${E(source.id)}" ${g.logSourceIds.includes(source.id)?'checked':''}>${E(source.name)}</label>`).join('')}</fieldset><div class="form-field"><label for="group-members">Discord-ID’s in deze rang</label><textarea id="group-members" name="memberIds" placeholder="Eén Discord-ID per regel of gescheiden door komma’s">${E((g.memberIds||[]).join('\n'))}</textarea><small>Toevoegen maakt meteen toegang aan. Een ID weghalen trekt de toegang via deze rang in. Je vaste Directie-account blijft apart.</small></div></form><div class="modal-actions"><button class="button" data-cancel>Annuleren</button><button class="button primary" data-confirm ${state.preview?'disabled':''}>Beheerrang opslaan</button></div>`,async()=>{
    const form=document.getElementById('group-editor');if(!form.reportValidity())throw Error('Vul een rangnaam in.');
    const f=new FormData(form);const memberIds=[...new Set(String(f.get('memberIds')||'').split(/[\s,;]+/).filter(Boolean))];
    await api('/api/account-groups',{method:'POST',body:JSON.stringify({id:g.id,name:f.get('name'),color:f.get('color'),permissions:f.getAll('permissions'),logSourceIds:f.get('allSources')?['*']:f.getAll('logSourceIds'),memberIds})});toast('Beheerrang en gekoppelde accounts opgeslagen.');await loadPage();
  });
  document.getElementById('group-editor')?.addEventListener('submit',e=>{e.preventDefault();document.querySelector('[data-confirm]')?.click()});
}
function updateDemotionOptions(){
  const form=document.getElementById('personnel-form');if(!form)return;
  const member=state.members.find(m=>m.id===form.elements.discordId.value.trim());
  const info=document.getElementById('person-current');if(info)info.textContent=member?'Huidige rang: '+(member.rank?.name||'Geen personeelsrang'):'De medewerker moet in de Royal Cars Discord-server zitten.';
  const select=document.getElementById('person-rank');if(!select||state.action!=='demote')return;
  const previous=select.value;const choices=state.ranks.filter(r=>!member?.rank||r.order>member.rank.order);
  select.innerHTML='<option value="">Kies de nieuwe, lagere rang</option>'+choices.map(r=>`<option value="${E(r.id)}">${E(r.name)}</option>`).join('');if(choices.some(r=>r.id===previous))select.value=previous;
}
document.addEventListener('click',async e=>{
  const b=e.target.closest('button');if(!b)return;
  if(b.hasAttribute('data-new-group')){groupEditor();return}
  if(b.hasAttribute('data-edit-group')){groupEditor(state.groups.find(g=>g.id===b.dataset.editGroup));return}
  if(b.hasAttribute('data-delete-group')){const g=state.groups.find(g=>g.id===b.dataset.deleteGroup);openModal(`<h2 id="modal-title">Beheerrang verwijderen?</h2><p>De rang ${E(g?.name)} wordt verwijderd. Accounts die uitsluitend deze rang hebben, verliezen direct toegang. Discord-rollen blijven behouden.</p><div class="modal-actions"><button class="button" data-cancel>Annuleren</button><button class="button danger" data-confirm>Rang verwijderen</button></div>`,async()=>{await api('/api/account-groups/'+encodeURIComponent(b.dataset.deleteGroup),{method:'DELETE'});toast('Beheerrang verwijderd.');await loadPage()});return}
  if(b.hasAttribute('data-copy-id')){try{await navigator.clipboard.writeText(b.dataset.copyId);toast('Discord-ID gekopieerd.')}catch{toast('Discord-ID: '+b.dataset.copyId)}}
});
document.addEventListener('change',e=>{if(e.target.id==='account-group')updateAccountMode();if(e.target.id==='person-id')updateDemotionOptions()});
document.addEventListener('input',e=>{if(e.target.id==='person-id')updateDemotionOptions()});
document.addEventListener('reset',e=>{if(e.target.id==='account-form')queueMicrotask(updateAccountMode)});
